//! A template backend's source map as provenance of the render module the
//! SFC assembly splices into the component (#13547).
//!
//! The DOM and SSR backends record where each emitted token of the render
//! function was authored and return those links as a Source Map v3 document
//! over the function alone. The SFC assembly needs them in the coordinates it
//! works in: generated bytes of the flattened render module, authored bytes of
//! the `.vue` file. Nothing here re-derives a position; it only relocates the
//! links the backend recorded.

use vize_l1_to_l2::lower::pug::PugSourceMap;
use vize_l4::module::OutputModule;

use crate::module_map::{Runs, source_map_points};
use crate::types::SfcTemplateBlock;

/// The links of `raw`, a backend map over `module.functions`, as points from
/// the flattened module into the authored SFC.
///
/// `template` places the block in its file; `pug` maps the derived HTML the
/// backend compiled back to the authored Pug.
pub(super) fn render_map(
    raw: Option<&str>,
    module: &OutputModule,
    template: &SfcTemplateBlock<'_>,
    pug: Option<&PugSourceMap>,
) -> Option<Runs> {
    let function = source_map_points(raw?, &module.functions, &template.content)?;
    let base = module.function_base_offset();
    let mut placed = Runs::default();
    for &(generated, authored) in function.points() {
        let authored = pug.map_or(authored, |map| map.offset_to_pug(authored as u32) as usize);
        placed.point(base + generated, template.loc.start + authored);
    }
    Some(placed)
}
